/*
 * Fastbit logo, three sizes, RGB565 (LV_IMG_CF_TRUE_COLOR, no alpha).
 *
 * fastbit_logo_dsc       -- 180x54, F429 splash screen. Generated from
 *                           FASTBIT_EMBEDDED_Logo_2_300x@2x.avif, which
 *                           carries its own solid navy-blue background
 *                           baked in, so it is legible on both a white
 *                           background (F429 splash) and a black one.
 * fastbit_logo_small_dsc -- 110x31, Device Monitor header corner logo,
 *                           v1 only (F746G). Replaced (2026-09-18) with
 *                           a new source image, "fastbit embedded
 *                           logo.png" -- a real alpha-transparent PNG
 *                           (unlike every earlier logo asset in this
 *                           file, which had a checkerboard or solid
 *                           colour baked into its RGB pixels instead
 *                           of genuine transparency). Composited
 *                           straight onto black (its alpha channel is
 *                           trustworthy here, confirmed by reading it
 *                           directly), which matches the header's own
 *                           background, so the logo's white chip icon
 *                           + wordmark sit directly on the screen with
 *                           no visible seam.
 * fastbit_logo_big_dsc   -- 300x90, F746G splash screen. Same navy
 *                           source as fastbit_logo_dsc, larger --
 *                           the 180x54 size looked too small on the
 *                           480x272 screen per explicit feedback. Not
 *                           the source's full native 400x120 -- that
 *                           would cost ~96KB flash vs this size's
 *                           ~54KB, and this build's flash budget has
 *                           limited headroom.
 *
 * Generated via Pillow (resize/composite as needed) + manual RGB565
 * packing. No LV_COLOR_16_SWAP on this build (confirmed in the
 * generated .config), so bytes are plain little-endian RGB565, low
 * byte first per pixel.
 *
 * Regenerate if either source image changes -- this is a static data
 * file, not something to hand-edit.
 */

#include <lvgl.h>

